r.forEach((v,i)=>text({label:jobs[i][0],result:v.status==="fulfilled"?v.value:String(v.reason)}));

const root="/Users/claraliu/Documents/ChatGPT/CS146S作业/study-repos/redis";
const jobs=[
 ["test-options",()=>tools.Grep({path:root+"/tests/test_helper.tcl",pattern:"single|--only|numclients|seconds|milliseconds|run_solo|--list-tests|retry|flak|\\.tcl|baseport",output_mode:"content",head_limit:65})],
 ["unit-samples",()=>tools.Grep({path:root+"/tests/unit/type/string.tcl",pattern:"^\\s*(test |start_server)",output_mode:"content",head_limit:8})],
