 ["history-depth",()=>tools.Execute({command:"git -C \""+root+"\" rev-parse --is-shallow-repository && git -C \""+root+"\" rev-list '@{u}..HEAD' --count",summary:"Check history completeness and remote alignment",riskLevel:"low"})],
 ["test-framework",()=>tools.Grep({path:root+"/tests/support",pattern:"(?i)retry|flak|milliseconds|seconds|testname|find_tests|\\.tcl|redact|sanitize|mask|tags",output_mode:"content",head_limit:65})],
 ["observability",()=>tools.Grep({path:root+"/src",glob_pattern:"*.c",pattern:"(?i)opentelemetry|trace.?id|request.?id|sentry|bugsnag|rollbar|prometheus|statsd|mixpanel|amplitude|posthog|heap.?profil|prof.dump|serverLogRaw|redact|sanitize",output_mode:"content",head_limit:85})],
 ["ops-config",()=>tools.Grep({path:root+"/redis.conf",pattern:"(?i)experimental|feature|latency|histogram|profil|slowlog|health|redact|sanitize|logfile|protected-mode|requirepass|notify|tracking",output_mode:"content",head_limit:65})],
 ["release-tools",()=>tools.LS({directory_path:root+"/utils/releasetools"})],
 ["doc-generator",()=>tools.Read({file_path:root+"/utils/generate-module-api-doc.rb",limit:75})]
];
const r=await Promise.allSettled(jobs.map(j=>j[1]()));
r.forEach((v,i)=>{
 let value=v.status==="fulfilled"?v.value:String(v.reason);
 if(Array.isArray(value)) value=value.map(x=>x.path?{file:x.path.slice(root.length+1),line:x.line,text:x.text}:x);
 text({label:jobs[i][0],result:value});
});

